#include<bits/stdc++.h>
using namespace std;struct Act{int h,a,c,dq,dh,mo,lim,mi[5];};
int main(int ac,char**av){ifstream in(av[1]);int F,cap,cut,top,target,di,nd;in>>F>>cap>>cut>>top>>target>>di>>nd;int old[4];for(int&i:old)in>>i;Act act[4][8];int keep[8]={0,1,4,5,6,7,8,9};for(int h=0;h<4;h++)for(int a=0;a<8;a++){auto&t=act[h][a];in>>t.h>>t.a>>t.c>>t.dq>>t.dh>>t.mo>>t.lim;for(int&i:t.mi)in>>i;assert(t.h==h&&t.a==keep[a]);}vector<array<int,8>>dfa(nd);for(auto&v:dfa)for(int&i:v)in>>i;assert(in);uint64_t limit=ac>2?stoull(av[2]):2000000;int nr=cap-F+1,nq=top-cut+2; __uint128_t universe=(__uint128_t)nd*4*nq; for(int j=0;j<5;j++)universe*=nr; assert(universe<=((__uint128_t)UINT64_MAX)+1);auto enc=[&](int h,int q,array<int,5>Q,int d){uint64_t z=d;z=z*4+h;z=z*nq+(q<=cut?0:q-cut);for(int x:Q){assert(x>=F&&x<=cap);z=z*nr+x-F;}return z;};auto dec=[&](uint64_t z,int&h,int&q,array<int,5>&Q,int&d){for(int j=4;j>=0;j--){Q[j]=z%nr+F;z/=nr;}int k=z%nq;z/=nq;q=k?k+cut:cut;h=z%4;d=z/4;};vector<uint64_t>states;vector<uint32_t>prev;vector<int8_t>lab;unordered_map<uint64_t,uint32_t>idx;idx.reserve(limit*1.3);auto add=[&](uint64_t z,uint32_t p,int a){if(idx.count(z))return;idx[z]=states.size();states.push_back(z);prev.push_back(p);lab.push_back(a);};array<int,5>Qi;Qi.fill(F);for(int h=0;h<4;h++)for(int q=cut;q<=old[h];q++)if(q==cut||(q-h)%2==0)add(enc(h,q,Qi,di),UINT32_MAX,-1);uint64_t next=states.size();int dep=0;for(uint32_t si=0;si<states.size();si++){if(si==next){dep++;next=states.size();cerr<<"layer "<<dep<<" states "<<states.size()<<"\n";}int h,q,d;array<int,5>Q;dec(states[si],h,q,Q,d);for(int ai=0;ai<8;ai++){auto&t=act[h][ai];int dd=dfa[d][ai];if(dd<0)continue;int low=q==cut?cut-16:q;for(int qq=low;qq<=q;qq++){if((qq-h)%2)continue;bool ok=qq<=old[h];for(int j=0;j<5;j++)if(t.mi[j]>-900&&qq+t.mi[j]>Q[j])ok=false;if(!ok)continue;if(q==0&&h==0&&t.a==target){cout<<"status WITNESS depth "<<dep+1<<" states "<<states.size()<<"\n";vector<int>w{t.a};uint32_t u=si;vector<uint32_t>path;while(u!=UINT32_MAX){path.push_back(u);if(lab[u]>=0)w.push_back(lab[u]);u=prev[u];}reverse(w.begin(),w.end());reverse(path.begin(),path.end());cout<<"word";for(int a:w)cout<<" "<<a;cout<<"\n";for(auto id:path){int hh,qx,ds;array<int,5>Qs;dec(states[id],hh,qx,Qs,ds);cout<<hh<<" "<<qx<<" "<<ds;for(int x:Qs)cout<<" "<<x;cout<<"\n";}return 0;}if(qq>t.lim)continue;array<int,5>Q2;for(int j=0;j<5;j++){Q2[j]=Q[max(0,j-t.c)];if(t.c>=j)Q2[j]=max(Q2[j],qq+t.mo);}int q2=qq+t.dq;if(q2>top)continue;int h2=(h+t.dh)%4;assert(q2<=old[h2]);add(enc(h2,q2,Q2,dd),si,t.a);if(states.size()>=limit){cout<<"status CAP states "<<states.size()<<" depth "<<dep<<"\n";return 0;}}}}cout<<"status EXHAUSTED states "<<states.size()<<" depth "<<dep<<"\n";}
